#include <Aevrynd/WorldBuilder3D.h>
#include <Aevrynd/Mesh3D.h>
#include <algorithm>
#include <utility>

namespace Aevrynd {
Material3D CreateMaterialPreset3D(MaterialPreset3D preset,Color tint,bool castsShadow){Surface3D surface{};MaterialClass3D materialClass=MaterialClass3D::Surface;switch(preset){case MaterialPreset3D::Matte:surface={.86f,0,0,.94f};break;case MaterialPreset3D::Wood:surface={.76f,0,.015f,.88f};break;case MaterialPreset3D::Stone:surface={.92f,.02f,0,.82f};break;case MaterialPreset3D::Metal:surface={.18f,.92f,.015f,1};break;case MaterialPreset3D::Glass:surface={.08f,.12f,.08f,1};tint.a=(std::min)(tint.a,.42f);castsShadow=false;break;case MaterialPreset3D::Emissive:surface={.28f,.04f,.72f,1};castsShadow=false;break;case MaterialPreset3D::Foliage:surface={.88f,0,.025f,.84f};materialClass=MaterialClass3D::Foliage;break;case MaterialPreset3D::Water:surface={.1f,.06f,.08f,1};tint.a=(std::min)(tint.a,.78f);castsShadow=false;materialClass=MaterialClass3D::Water;break;}Material3D material{tint,surface,castsShadow};material.materialClass=materialClass;return material;}
void WorldBuilder3D::Initialize(Engine& engine){if(box_)return;box_=engine.CreateMeshResource3D(Mesh3D::CreateUnitBox());pyramid_=engine.CreateMeshResource3D(Mesh3D::CreateUnitPyramid());sphere_=engine.CreateMeshResource3D(Mesh3D::CreateUnitSphere(14,9));cylinder_=engine.CreateMeshResource3D(Mesh3D::CreateUnitCylinder(14));cone_=engine.CreateMeshResource3D(Mesh3D::CreateUnitCone(14));}
void WorldBuilder3D::Shutdown(Engine& engine,PhysicsWorld3D* physics){if(physics)for(const auto& [id,object]:objects_){(void)id;if(object.rigidBody)physics->DestroyBody(object.rigidBody);}for(const MeshResource3D* mesh:{&box_,&pyramid_,&sphere_,&cylinder_,&cone_})if(*mesh)engine.DestroyMesh3D(mesh->handle);std::unordered_map<uint32_t,WorldObject3D>{}.swap(objects_);box_=pyramid_=sphere_=cylinder_=cone_={};stats_={};}
const MeshResource3D& WorldBuilder3D::MeshFor(PrimitiveShape3D primitive)const{switch(primitive){case PrimitiveShape3D::Pyramid:return pyramid_;case PrimitiveShape3D::Sphere:return sphere_;case PrimitiveShape3D::Cylinder:return cylinder_;case PrimitiveShape3D::Cone:return cone_;default:return box_;}}
WorldObjectHandle3D WorldBuilder3D::Create(WorldObjectDefinition3D definition,PhysicsWorld3D* physics){if(!box_||definition.name.empty()||Find(definition.name))return{};const WorldObjectHandle3D handle{nextHandle_++};WorldObject3D object{handle,std::move(definition)};if(object.definition.collisionEnabled&&physics){const MeshBounds3D bounds=TransformBounds(MeshFor(object.definition.primitive).bounds,object.definition.transform);RigidBodySettings3D body{};body.type=object.definition.bodyType;body.transform=object.definition.transform;body.transform.position=bounds.center;body.colliderExtents=bounds.extents;body.material=object.definition.physicsMaterial;body.layer=object.definition.collisionLayer;body.collisionMask=object.definition.collisionMask;object.rigidBody=physics->CreateBody(body);}objects_.emplace(handle.value,std::move(object));++stats_.created;return handle;}
WorldObjectHandle3D WorldBuilder3D::Create(std::string name,PrimitiveShape3D primitive,Transform3D transform,MaterialPreset3D material,Color tint,RigidBodyType3D bodyType,PhysicsWorld3D* physics,MaterialTextureSetHandle3D textures,float textureScale){WorldObjectDefinition3D definition{};definition.name=std::move(name);definition.primitive=primitive;definition.transform=transform;definition.material=CreateMaterialPreset3D(material,tint);definition.material.textures=textures;definition.material.textureScale=(std::max)(.001f,textureScale);definition.bodyType=bodyType;return Create(std::move(definition),physics);}
bool WorldBuilder3D::Destroy(WorldObjectHandle3D handle,PhysicsWorld3D* physics){const auto found=objects_.find(handle.value);if(found==objects_.end())return false;if(physics&&found->second.rigidBody)physics->DestroyBody(found->second.rigidBody);objects_.erase(found);++stats_.destroyed;return true;}
WorldObject3D* WorldBuilder3D::Get(WorldObjectHandle3D handle){const auto found=objects_.find(handle.value);return found==objects_.end()?nullptr:&found->second;}
const WorldObject3D* WorldBuilder3D::Get(WorldObjectHandle3D handle)const{const auto found=objects_.find(handle.value);return found==objects_.end()?nullptr:&found->second;}
WorldObjectHandle3D WorldBuilder3D::Find(std::string_view name)const{for(const auto& [id,object]:objects_)if(object.definition.name==name)return{id};return{};}
bool WorldBuilder3D::SetTransform(WorldObjectHandle3D handle,Transform3D transform,PhysicsWorld3D* physics){WorldObject3D* object=Get(handle);if(!object)return false;object->definition.transform=transform;if(physics&&object->rigidBody)physics->SetTransform(object->rigidBody,transform);return true;}
bool WorldBuilder3D::SetMaterial(WorldObjectHandle3D handle,Material3D material){WorldObject3D* object=Get(handle);if(!object)return false;object->definition.material=material;return true;}
void WorldBuilder3D::Synchronize(const PhysicsWorld3D& physics){for(auto& [id,object]:objects_){(void)id;if(!object.rigidBody)continue;const RigidBodyState3D* body=physics.GetBody(object.rigidBody);if(body)object.definition.transform.position=body->settings.transform.position;}}
void WorldBuilder3D::Submit(Scene3D& scene)const{for(const auto& [id,object]:objects_){(void)id;if(!object.definition.visible)continue;scene.Mesh(MeshFor(object.definition.primitive),object.definition.transform,object.definition.material);++stats_.submitted;}}
WorldBuilderStats3D WorldBuilder3D::Stats()const{WorldBuilderStats3D result=stats_;result.objects=objects_.size();result.residentPrimitiveMeshes=box_?5:0;for(const auto& [id,object]:objects_){(void)id;if(object.definition.visible)++result.visibleObjects;if(object.definition.collisionEnabled)++result.colliders;if(object.definition.bodyType==RigidBodyType3D::Dynamic)++result.dynamicObjects;}return result;}
}
